/**
 * Mechanical enforcement of the knowledge base (docs/ + AGENTS.md). Agents read these files as the system of
 * record, so a dead link, an unindexed design doc or a stale generated file is a defect, caught in CI like any
 * other (harness/test/docs.test.ts). Each problem says how to fix it, because the reader is usually an agent.
 */
import { existsSync } from "node:fs";
import { readFile, readdir } from "node:fs/promises";
import path from "node:path";

export const AGENTS_MAX_LINES = 150;

async function walk(dir: string, out: string[] = []): Promise<string[]> {
  for (const e of await readdir(dir, { withFileTypes: true }).catch(() => [])) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) await walk(p, out);
    else out.push(p);
  }
  return out;
}

/** docs/generated/db-schema.md: the final schema of the reference room-booking build, from its migrations. */
export async function generateDbSchema(root: string): Promise<string> {
  const script = path.join(root, "examples", "room-booking", "script");
  // The latest attempt of a migration wins (sprint 5 attempt 2 is the one that shipped).
  const latest = new Map<string, { attempt: string; file: string }>();
  for (const f of (await walk(script)).filter((p) => p.endsWith(".sql")).sort()) {
    const attempt = /attempt-(\d+)/.exec(f)?.[1] ?? "0";
    const name = path.basename(f);
    const prev = latest.get(name);
    if (!prev || Number(attempt) >= Number(prev.attempt)) latest.set(name, { attempt, file: f });
  }
  const lines = [
    "<!-- GENERATED by `npm run docs:gen` from examples/room-booking/script/**/migrations. Do not edit by hand. -->",
    "# Database schema (room-booking reference build)",
    "",
    "Final schema after all six sprints of the recorded run. The tables an agent will meet in the workspace.",
    "",
  ];
  const tables: string[] = [];
  const sections: string[] = [];
  for (const name of [...latest.keys()].sort()) {
    const { file } = latest.get(name)!;
    const sql = (await readFile(file, "utf8")).trim();
    for (const m of sql.matchAll(/CREATE TABLE (?:IF NOT EXISTS )?(\w+) \(([\s\S]*?)\n\);/g)) {
      const cols = m[2]!.split("\n").map((l) => l.trim().replace(/,$/, ""))
        .filter((l) => /^[a-z_]+\s/.test(l) && !/^(CHECK|UNIQUE|PRIMARY|CONSTRAINT)/i.test(l))
        .map((l) => `\`${l.split(/\s+/)[0]}\``);
      tables.push(`| \`${m[1]}\` | ${cols.join(", ")} | ${name} |`);
    }
    sections.push(`### ${name}`, "", `Source: \`${path.relative(root, file).split(path.sep).join("/")}\``, "", "```sql", sql, "```", "");
  }
  lines.push("| Table | Columns | Created in |", "|---|---|---|", ...tables, "", "## Migrations", "", ...sections);
  return lines.join("\n");
}

const LINK = /\[[^\]]*\]\(([^)\s]+)\)/g;

export async function checkDocs(root: string): Promise<string[]> {
  const problems: string[] = [];
  const rel = (p: string) => path.relative(root, p).split(path.sep).join("/");

  const agents = path.join(root, "AGENTS.md");
  if (!existsSync(agents)) problems.push("AGENTS.md is missing: it is the agent's entry point");
  else {
    const n = (await readFile(agents, "utf8")).split("\n").length;
    if (n > AGENTS_MAX_LINES)
      problems.push(`AGENTS.md has ${n} lines (max ${AGENTS_MAX_LINES}): it is a map, move detail into docs/ and link it`);
  }

  // Every relative link in the knowledge base must resolve.
  const mds = [agents, path.join(root, "ARCHITECTURE.md"), ...(await walk(path.join(root, "docs")))].filter((p) => p.endsWith(".md") && existsSync(p));
  for (const md of mds) {
    const text = (await readFile(md, "utf8")).replace(/```[\s\S]*?```/g, "");
    for (const [, target] of text.matchAll(LINK)) {
      if (/^(https?:|mailto:|#)/.test(target!)) continue;
      const file = path.resolve(path.dirname(md), target!.split("#")[0]!);
      if (!existsSync(file)) problems.push(`${rel(md)}: broken link "${target}" (fix the path or remove the link)`);
    }
  }

  // Indexes list every document in their folder, so progressive disclosure never hides a file.
  for (const dir of ["docs/design-docs", "docs/product-specs"]) {
    const index = path.join(root, dir, "index.md");
    if (!existsSync(index)) { problems.push(`${dir}/index.md is missing`); continue; }
    const text = await readFile(index, "utf8");
    for (const f of (await readdir(path.join(root, dir))).filter((f) => f.endsWith(".md") && f !== "index.md"))
      if (!text.includes(`(${f})`)) problems.push(`${dir}/index.md does not link ${f}: add a row for it`);
  }

  // Execution plans carry their state; the folder must agree with it.
  for (const [dir, want] of [["active", /^Status: (proposed|in-progress|blocked)\b/m], ["completed", /^Status: completed\b/m]] as const) {
    for (const f of (await walk(path.join(root, "docs", "exec-plans", dir))).filter((p) => p.endsWith(".md"))) {
      const text = await readFile(f, "utf8");
      if (!want.test(text))
        problems.push(`${rel(f)}: needs a "Status: ${dir === "active" ? "proposed|in-progress|blocked" : "completed"}" line (or move it to the other folder)`);
    }
  }

  // Generated docs must match their source.
  const schema = path.join(root, "docs", "generated", "db-schema.md");
  if (!existsSync(schema) || (await readFile(schema, "utf8")) !== (await generateDbSchema(root)))
    problems.push("docs/generated/db-schema.md is stale: run `npm run docs:gen`");

  return problems;
}
